import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value())


def pnum(text):
    return int(re.sub(r"\D", "", text))


def parse_offset(text):
    text = text.strip()
    sign = -1 if text.startswith("-") else 1
    hours, minutes = text.lstrip("+-").split(":")
    return sign * (int(hours) * 60 + int(minutes))


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle))


def load_policy(path):
    cp = configparser.RawConfigParser(interpolation=None, inline_comment_prefixes=None)
    cp.optionxform = str
    with open(path, encoding="utf-8-sig") as handle:
        cp.read_file(handle)
    pol = {"items": {}, "cats": {}}
    st = cp["statement"]
    pol["library"] = st["library"].strip()
    pol["start"] = date.fromisoformat(st["period_start"].strip())
    pol["end"] = date.fromisoformat(st["period_end"].strip())
    clock = cp["clock"] if cp.has_section("clock") else {}
    base = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        when, off = part.split()
        instant = datetime.strptime(when, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
        changes.append((instant, parse_offset(off)))
    changes.sort()
    pol["base"] = base
    pol["changes"] = changes
    for name in cp.sections():
        if name.lower().startswith("item:"):
            sec = cp[name]
            pol["items"][name[5:].strip().lower()] = {
                "name": name[5:].strip(),
                "loan_days": int(sec["loan_days"]),
                "renewals": int(sec["renewals"]),
                "grace": int(sec["grace_days"]),
                "daily": cents(sec["daily"]),
                "loan_cap": cents(sec["loan_cap"]),
            }
        elif name.lower().startswith("category:"):
            sec = cp[name]
            cap = sec["statement_cap"].strip()
            pol["cats"][name[9:].strip().lower()] = {
                "name": name[9:].strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(sec["discount"]),
                "exempt": {x.strip().lower() for x in sec.get("exempt", "").split(",") if x.strip()},
            }
    return pol


def local_from_instant(text, pol):
    text = text.strip()
    if text.endswith(("Z", "z")):
        text = text[:-1] + "+00:00"
    moment = datetime.fromisoformat(text)
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    moment = moment.astimezone(timezone.utc)
    offset = pol["base"]
    for instant, off in pol["changes"]:
        if moment >= instant:
            offset = off
    return moment.replace(tzinfo=None) + timedelta(minutes=offset)


def load_events(input_dir, pol):
    events = {}
    folder = os.path.join(input_dir, "exports")
    for name in sorted(os.listdir(folder)):
        if not name.endswith((".csv", ".jsonl")):
            continue
        path = os.path.join(folder, name)
        if name.endswith(".csv"):
            rows = read_csv(path)
            for row in rows:
                row = {k: (v or "").strip() for k, v in row.items() if k}
                if row.get("event") and row["event"] not in events:
                    row["local"] = datetime.strptime(row["time"], "%Y-%m-%d %H:%M")
                    events[row["event"]] = row
