        returned = None
        for ev in sorted(follow.get(loan_id, []), key=lambda e: e["local"]):
            day = ev["local"].date()
            if ev["type"].lower() == "renew":
                if day <= due and renewals < item["renewals"] and day <= end:
                    renewals += 1
                    due = cal.next_open(branch, day + timedelta(days=item["loan_days"]))
            else:
                returned = day - timedelta(days=1) if ev.get("via", "").lower() == "dropbox" else day
                break
        if returned is not None and returned < start:
            continue
        still_out = returned is None or returned > end
        end_day = end if still_out else returned
        overdue = 0
        probe = due + timedelta(days=1)
        while probe <= end_day:
            if cal.is_open(branch, probe):
                overdue += 1
            probe += timedelta(days=1)
        if overdue == 0:
            continue
        number = pnum(co["patron"])
        rows = patron_rows[number]
        cat = pol["cats"][category_on(rows, out_day)["category"].strip().lower()]
        charged = overdue if overdue > item["grace"] else 0
        base = charged * item["daily"]
        if item["name"].lower() in cat["exempt"]:
            base = 0
        base = min(base, item["loan_cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        amount = 0
        full = False
        for w in waivers:
            if pnum(w["patron"]) != number or w["loan"].strip() not in (loan_id, "*"):
                continue
            if w["value"].strip().lower() == "full":
                full = True
            else:
                amount += cents(w["value"])
        waived = assessed if full else min(amount, assessed)
        loans.append({
            "number": number, "due_date": due,
            "loan": loan_id, "item": co["item"], "item_type": item["name"], "branch": branch,
            "checkout": out_day.isoformat(), "due": due.isoformat(),
            "returned": None if still_out else returned.isoformat(),
            "overdue_days": overdue, "charged_days": charged,
            "assessed": assessed, "waived": waived, "capped": 0, "billed": assessed - waived,
        })

    by_patron = {}
    for loan in loans:
        by_patron.setdefault(loan["number"], []).append(loan)
    statements = []
    for number in sorted(by_patron):
        group = by_patron[number]
        rows = patron_rows[number]
        cat_row = category_on(rows, end)
        cat = pol["cats"][cat_row["category"].strip().lower()]
        net_total = sum(x["billed"] for x in group)
        if cat["cap"] is not None and net_total > cat["cap"]:
            excess = net_total - cat["cap"]
            ordered = sorted(group, key=lambda x: x["loan"], reverse=True)
            ordered.sort(key=lambda x: x["due_date"], reverse=True)
            for loan in ordered:
                give = min(loan["billed"], excess)
                loan["capped"] = give
                loan["billed"] -= give
                excess -= give
        group.sort(key=lambda x: (x["due_date"], x["loan"]))
        entry = {"patron": cat_row["patron"].strip(), "category": cat["name"],
                 "loans": [{k: v for k, v in x.items() if k not in ("number", "due_date")} for x in group]}
        for key in ("assessed", "waived", "capped", "billed"):
            entry[key] = sum(x[key] for x in group)
        statements.append(entry)

    branches = []
    for branch in cal.open_days:
        mine = [x for s in statements for x in s["loans"] if x["branch"] == branch]
        row = {"branch": branch, "loans": len(mine), "charged_days": sum(x["charged_days"] for x in mine)}
        for key in ("assessed", "waived", "capped", "billed"):
            row[key] = sum(x[key] for x in mine)
        branches.append(row)

    result = {"library": pol["library"], "period": {"start": start.isoformat(), "end": end.isoformat()},
              "statements": statements, "branches": branches}
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(result, handle, indent=2, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
